                    let visibleEdges = edges.filter(item => isVisibleVector(item));
                    return filterBlocks(visibleEdges, { ...expandedPadding, strictIntersecting: false })
                      .filter(item => !paddingObj.x.includes(item.x) && !paddingObj.y.includes(item.y))
                      .length;
